try{$u=tt_require_login();if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET')mrr_out(['ok'=>false,'error'=>'Recovery reports are read-only.'],405);$e=strtoupper(trim((string)($_GET['entity']??'TTI')));if(!in_array($e,['TTI','BRM'],true))mrr_out(['ok'=>false,'error'=>'Choose TTI or BRM production books.'],422);$allowed=tt_inv_can_report($u,$e)||(tt_user_can_open_module($u,'Mill')&&tt_inv_has_action($u,'Mill',['reports','production'])&&tt_user_can_access_entity($u,$e,'View'));if(!$allowed)mrr_out(['ok'=>false,'error'=>'Production report access for this company is required.'],403);$filters=['entity'=>$e];foreach(['from','to','shift','variety','mill','brand','contract','mode'] as $k)$filters[$k]=trim((string)($_GET[$k]??''));if(!in_array($filters['mode'],['daily','production','brand','contract'],true))$filters['mode']='daily';foreach(['from','to'] as $k)if($filters[$k]!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$filters[$k]))mrr_out(['ok'=>false,'error'=>'Valid report dates are required.'],422);if($filters['from']!==''&&$filters['to']!==''&&$filters['from']>$filters['to'])mrr_out(['ok'=>false,'error'=>'From date cannot follow To date.'],422);tt_release_read_session();$file=TT_DATA_DIR.'/operations.json';$ops=[];if(is_file($file)){$h=fopen($file,'r');if(!$h||!flock($h,LOCK_SH))throw new RuntimeException();try{$ops=json_decode(stream_get_contents($h),true,512,JSON_THROW_ON_ERROR);}finally{flock($h,LOCK_UN);fclose($h);}if(!is_array($ops))throw new RuntimeException();}$values=(array)($ops['values']??[]);$rows=tt_inv_rows($values,'tt30prod');mrr_out(mr_report($rows,$filters));}catch(Throwable $e){error_log('Mill recovery report: '.$e->getMessage());mrr_out(['ok'=>false,'error'=>'Recovery source could not be read. No figures have been estimated.'],500);}
